function UIBattlingDiscoverCard:InitCardList(star)
    local posData = { self.skillCard.curTransArrLinePos, self.skillCard.curTransArrLine }
    --- 队友人数 技能 
    if self.listRoleCell then self.listRoleCell = {} end
    if isNull(SkillPoolOperationMgr.listAvailableRole) then return end
    for i = 1, #SkillPoolOperationMgr.listAvailableRole do
        local roleView = SkillPoolOperationMgr.listAvailableRole[i]
        local roleId = roleView.id
        local go = KTool.Instantiate(self.CardList.gameObject, self.CharactorCell.gameObject)
        if not IsNull(go) then
            local lbCell = KTool.GetComponent(go, typeof(LuaBehaviour))
            if not IsNull(lbCell) then
                lbCell:Init()
                local ltCell = lbCell.Env
                if ltCell then
                    ltCell:SetCallBack(function(data2Logic)
                        UIModule.CloseDialog(self.controller)
                        if self.callBack then
                            self.callBack(data2Logic)
                        end
                    end)
                    ltCell:InitCellInfo(roleId, posData, star, self.cardBehaviorParam)
                    table.insert(self.listRoleCell, ltCell)
                    KTool.SetActive(ltCell.controller.gameObject, true)
                end
            end
        end
    end
end

